import{_ as e,c as a,d as r,Z as l}from"./chunks/framework.B0uuYL3Y.js";const m=JSON.parse('{"title":"Spectre 变体中的分支与访存推测","description":"用分支方向、间接目标与内存依赖对照不同瞬态来源，并核对缓解措施的作用范围。","frontmatter":{"title":"Spectre 变体中的分支与访存推测","description":"用分支方向、间接目标与内存依赖对照不同瞬态来源，并核对缓解措施的作用范围。","date":"2026-11-25","tags":["微架构安全","瞬态执行","分支预测","BHB","缓解措施"],"book":"microarch-00-intro"},"headers":[],"relativePath":"posts/microarch-04c-variants.md","filePath":"posts/microarch-04c-variants.md"}'),n={name:"posts/microarch-04c-variants.md"};function i(c,t,o,s,h,d){return a(),r("div",null,t[0]||(t[0]=[l('<p><a href="./microarch-04d-spectre-v1.html">Spectre v1</a>的关键时刻是边界检查的分支方向得到确认。读其他推测执行问题时，也可以先找出哪个条件还未确定，再说明执行端怎样确认它、在此之前已经发生了哪些内部活动。</p><nav class="table-of-contents"><ul><li><a href="#从预测方向换到预测目标">从预测方向换到预测目标</a></li><li><a href="#把另一个前提换成访存依赖">把另一个前提换成访存依赖</a></li><li><a href="#怎样核对一个缓解措施适用到哪里">怎样核对一个缓解措施适用到哪里</a></li><li><a href="#参考文献">参考文献</a></li></ul></nav><h2 id="从预测方向换到预测目标" tabindex="-1">从预测方向换到预测目标 <a class="header-anchor" href="#从预测方向换到预测目标" aria-label="Permalink to &quot;从预测方向换到预测目标&quot;">​</a></h2><p>以解释器为例。不同操作码需要调用不同处理函数，运行时经常通过间接跳转决定去往哪个函数。前端可以先取预测的处理函数中的指令。实际目标算出后，若与预测不符，错误处理函数中的相关工作会被撤销。这里的分支可以是无条件跳转，所以预测问题不是“跳还是不跳”，而是“跳到哪个目标”。</p><p><strong>Spectre v2</strong> 关注间接分支的预测目标。先核对间接目标依赖哪份预测状态，再看错误路径的内部活动是否因受保护信息改变。最后结合<a href="./microarch-04b-observation.html">观察条件</a>判断这种变化能否被区分。只知道错预测总数上升，还无法定位到一次方向错误或目标错误。</p><p>这也决定了缓解措施的解释范围。某项措施限制信任域间间接分支预测状态的影响时，它首先作用于变体的触发条件。共享缓存、正常访存和计时可见性仍需要单独判断。当一个问题被称为变体时，可以回到前面几章逐项定位：改变了哪一部分硬件状态，改变发生在哪一阶段，因果链中剩下哪些环节还需要证据。</p><p>分析间接目标的影响还需细分状态。用于保存预测目标的表项和参与选择的分支历史，可以有不同的隔离规则。因此，比较措施前先查它覆盖的是预测项、选择条件，还是某类控制转移。<a href="./microarch-03a-fetch-prediction.html#predict-isolation">BHB 一节</a>用两个预测模式推演了目标项隔离与历史隔离的区别。</p><h2 id="把另一个前提换成访存依赖" tabindex="-1">把另一个前提换成访存依赖 <a class="header-anchor" href="#把另一个前提换成访存依赖" aria-label="Permalink to &quot;把另一个前提换成访存依赖&quot;">​</a></h2><p><a href="./microarch-03d-load-store.html#lsu-replay">存储地址迟到时的重试</a>展示了普通程序里的顺序失败。较老存储的地址未知时，年轻加载可能先从缓存取得旧值。如果后来发现两者重叠，处理器就需要重试。若地址已经确认重叠、只是存储数据未就绪，加载会等待数据。这里未解决的条件是<strong>两条访存是否重叠以及数据应该来自哪一方</strong>。条件分支方向和间接跳转目标都可以正确，执行中仍会有这类推测。</p><p>Intel 的资料用 Speculative Store Bypass 描述相关风险类别。把它放回时序中读：加载得到可供后继暂时使用的值，后来确定顺序，架构结果按规则更新。要说明安全影响，还需有证据把先前暂时使用的值和某项受影响的资源连起来，并把资源差异连接到给定观察者。正常的 store-to-load forwarding、较老存储地址未决时的早发和后续顺序恢复可以在同一访存系统出现，分析时应分别定位。</p><table tabindex="0"><thead><tr><th>还待确定的条件</th><th>去哪里找负责确认的逻辑</th><th>恢复前可能存在的工作</th></tr></thead><tbody><tr><td>条件分支走哪边</td><td>分支操作数就绪后的比较</td><td>预测方向上的较年轻操作</td></tr><tr><td>间接分支去哪儿</td><td>用运行时操作数求出实际目标</td><td>预测目标处的较年轻操作</td></tr><tr><td>先前存储是否与加载重叠</td><td>地址就绪后的访存顺序检查</td><td>已使用加载初次结果的操作</td></tr></tbody></table><h2 id="怎样核对一个缓解措施适用到哪里" tabindex="-1">怎样核对一个缓解措施适用到哪里 <a class="header-anchor" href="#怎样核对一个缓解措施适用到哪里" aria-label="Permalink to &quot;怎样核对一个缓解措施适用到哪里&quot;">​</a></h2><p>先写清楚措施要改变表中的哪一格。例如核对跨预测模式的间接目标限制时，应分别检查已学习表项的使用范围和参与选择的历史；两者可以由不同控制约束。若讨论面向内存依赖的措施，则要看它约束的是存储地址未决时的加载行为。比较不同部署还需记录型号、微码、系统代码与媒体资料的适用条件。真实排查应以平台对应的缓解说明为准。</p><details class="details custom-block"><summary>练习：某项控制解决了哪一步</summary><p>假设某平台的资料只证明“切换到新预测模式后，间接目标不能从旧模式的表项取得”。从这一点能推出条件分支推测或存储重叠预测也受到同样限制吗？如果要进一步论证 BHB 不会产生跨模式影响，还需什么资料？</p><p>这条保证只覆盖特定范围的间接目标选择。前两类问题使用不同的判断与恢复逻辑，需要各自的证据。即使间接预测只能取当前模式的项，仍需确认旧历史是否会被用于挑选这些项。针对历史的保证或实测证据才支持后一项判断。</p></details><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li><a href="https://www.intel.com/content/www/us/en/developer/articles/technical/software-security-guidance/technical-documentation/analysis-speculative-execution-side-channels.html" target="_blank" rel="noreferrer">Intel 机制说明</a></li><li><a href="https://www.intel.com/content/www/us/en/developer/articles/technical/software-security-guidance/technical-documentation/speculative-execution-side-channel-mitigations.html" target="_blank" rel="noreferrer">Intel 缓解说明</a></li><li><a href="https://www.intel.com/content/www/us/en/developer/articles/technical/software-security-guidance/technical-documentation/hardware-behavior-related-to-speculative-execution.html" target="_blank" rel="noreferrer">Intel 推测执行硬件行为</a></li><li><a href="https://www.intel.com/content/www/us/en/developer/articles/technical/software-security-guidance/technical-documentation/branch-history-injection.html" target="_blank" rel="noreferrer">Intel BHI 的历史边界</a></li><li><a href="https://docs.kernel.org/admin-guide/hw-vuln/index.html" target="_blank" rel="noreferrer">Linux 的处理器漏洞与缓解说明</a></li></ul><nav class="article-nav" aria-label="系列文章导航"><p><a href="./microarch-04e-meltdown.html" class="article-nav-card article-nav-prev" rel="prev"><span class="article-nav-text"><small>上一篇</small><strong>Meltdown 中的越权加载如何影响后续指令</strong></span></a></p><p><a href="./microarch-05-sources.html" class="article-nav-card article-nav-next" rel="next"><span class="article-nav-text"><small>下一篇</small><strong>微架构安全学习资料</strong></span></a></p></nav>',17)]))}const u=e(n,[["render",i]]);export{m as __pageData,u as default};
